  voice('motor','triangle',65,this.fx);voice('regen','sine',150,this.fx);voice('rotor','sawtooth',90,this.fx);voice('machine','triangle',60,this.ambient);voice('wind','',350,this.ambient,true);voice('tire','',700,this.fx,true);voice('rattle','',1800,this.fx,true);voice('static','',2900,this.fx,true);voice('river','',900,this.ambient,true);voice('industrial','sine',48,this.ambient);
